// QueryRing queries the ring edge of a RingVersion.
func (c *RingVersionClient) QueryRing(_m *RingVersion) *RingQuery {
	query := (&RingClient{config: c.config}).Query()
	query.path = func(context.Context) (fromV *sql.Selector, _ error) {
		id := _m.ID
		step := sqlgraph.NewStep(
			sqlgraph.From(ringversion.Table, ringversion.FieldID, id),
			sqlgraph.To(ring.Table, ring.FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, ringversion.RingTable, ringversion.RingColumn),
		)
		fromV = sqlgraph.Neighbors(_m.driver.Dialect(), step)
		return fromV, nil
	}
	return query
}

